        asr     a
        move    a,x0
        mpy     x0,y1,a
        asl     a
        add     b,a
        move    a,x:(r0)+
; ---- right ----
        move    x:(r0),x0
        move    x:(r7+$01),y0
        mpy     y0,x0,a
        asl     #$4,a,a  ; g x / s
        move    x:(r7+$06),x1
        add     x1,a  ; + b
        move    #>$7fffff,x1
        cmp     x1,a
        tgt     x1,a
        move    #>$800000,x1
        cmp     x1,a
        tlt     x1,a
        move    a,x0
        mpy     x0,x0,a
        move    a,y0  ; w = u^2
        move    #>$180000,x1
        mpy     x1,y0,a
        sub     #>$500000,a
        move    a,x1
        mpy     x1,y0,a
        add     #>$780000,a
        move    a,y0
        mpy     y0,x0,a  ; f/2 = u (15 - 10 w + 3 w^2)/16
        move    x:(r7+$07),x1
        sub     x1,a  ; (f(u) - f(b))/2
        move    a,x0
; DC blocker: lp += c (z - lp); z - lp (high word)
        move    x:(r7+$14),a
        move    x:(r7+$15),a0
        move    #>$002ea7,y1
        mac     x0,y1,a
        move    x:(r7+$14),x1
        mac     -y1,x1,a
        move    a1,x:(r7+$14)
        move    a0,x:(r7+$15)
        move    a1,x1
        move    x0,a
        sub     x1,a
        move    a,x0
        move    x0,x:(r7+$16)
        clr     a
        move    a,x:(r7+$17)  ; open: the lowpass follows
        move    x:(r7+$03),y0
        mpy     y0,x0,a
        asl     #$2,a,a  ; y x LEVL
        move    x:(r7+$05),y1
        move    x:(r0),b
        sub     b,a
        asr     a
        move    a,x0
        mpy     x0,y1,a
        asl     a
        add     b,a
        move    a,x:(r0)+
wmendto:
        nop     
        rts     
wmexp:
        move    a1,b
        asr     #$12,a,a  ; a1 = n = floor(y)
        add     #>$1,a
        move    a1,x1  ; n + 1 (never 0: a do count of 0 is not a skip)
        and     #>$03ffff,b
        asl     #$5,b,b  ; f in Q23, b2 stays 0
        move    b1,x0
        move    #>$2c5c86,y0
        mpy     y0,x0,b
        move    b,y0  ; g = f ln2 / 2
        move    #>$02aaab,x0
        mpy     y0,x0,b
        sub     #>$0aaaab,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$200000,b
        move    b,x0
        mpy     y0,x0,b
        sub     #>$400000,b
        move    b,x0
        mpy     y0,x0,b
        add     #>$400000,b  ; e^-g / 2
        move    b,x0
        mpy     x0,x0,b
        asl     #$2,b,b  ; 2^-f in (0.5, 1]
        do      x1,>wmxpend
        asr     b
wmxpend:
        asl     b
        rts     
